import{_ as o}from"./chunks/爆炸图-HK.Up-J1OV1.js";import{_ as a}from"./chunks/Bottom_Mount.B5GL5t7z.js";import{_ as r,c as n,o as s,a0 as l}from"./chunks/framework._Jgw3yL-.js";const b=JSON.parse('{"title":"基礎-客制化鍵盤外殼與内膽","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/HAWKZ-jelly102-HK/键盘内胆.md","filePath":"zh-HK/HAWKZ-jelly102-HK/键盘内胆.md"}'),e={name:"zh-HK/HAWKZ-jelly102-HK/键盘内胆.md"};function i(g,t,h,m,d,u){return s(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="基礎-客制化鍵盤外殼與内膽" tabindex="-1">基礎-客制化鍵盤外殼與内膽 <a class="header-anchor" href="#基礎-客制化鍵盤外殼與内膽" aria-label="Permalink to &quot;基礎-客制化鍵盤外殼與内膽&quot;">​</a></h1><div class="image-row image-row-2"><div class="image-item"><img src="'+o+'" alt="鍵盤爆炸圖" class="zoom-medium"><div>鍵盤爆炸圖</div></div></div><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><h1 id="基礎-客製化鍵盤結構與設計" tabindex="-1">基礎-客製化鍵盤結構與設計 <a class="header-anchor" href="#基礎-客製化鍵盤結構與設計" aria-label="Permalink to &quot;基礎-客製化鍵盤結構與設計&quot;">​</a></h1><ul><li>基礎訂製整體結構的内部設計採用的是： <strong>Bottom Mount</strong>。 <br></li><li>基礎訂製的外殼結構的設計採用使用的是： <strong>天包地結構</strong>。</li></ul><h2 id="bottom-mount-定位板固定在底殼" tabindex="-1"><strong>Bottom Mount（定位板固定在底殼）</strong> <a class="header-anchor" href="#bottom-mount-定位板固定在底殼" aria-label="Permalink to &quot;**Bottom Mount（定位板固定在底殼）**&quot;">​</a></h2><p>這種結構有一點點像 Tray mount，但它並非固定在底殼內部，而是固定在底殼邊緣，中間有很好的伸展性，從而得到更多並且更均勻的剛性結構支撐。同時，這種結構不需要上蓋的參與，從而可以設計成懸浮式外觀。個人覺得會比 Top mount 稍微硬一點。<br></p><p><img src="'+a+'" alt=" "></p><ul><li>✅ <strong>優點</strong></li></ul><p>內膽與外殼固定非常扎實，手感一致性很好。</p><h2 id="天包地-上蓋包裹底殼" tabindex="-1"><strong>天包地（上蓋包裹底殼）</strong> <a class="header-anchor" href="#天包地-上蓋包裹底殼" aria-label="Permalink to &quot;**天包地（上蓋包裹底殼）**&quot;">​</a></h2><p>「天包地」是機械鍵盤圈子裡描述外殼結構的常見術語，指的是一種<strong>上蓋包裹住底殼</strong>的設計。</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><ul><li><strong>天</strong>：鍵盤的<strong>上蓋</strong>。</li><li><strong>包</strong>：<strong>包裹、覆蓋</strong>。</li><li><strong>地</strong>：鍵盤的<strong>底殼</strong>。</li></ul><p>簡單來說，「天包地」就是 <strong>上蓋的邊緣向下延伸，從外側包住底殼的邊緣</strong>，類似一個「蓋子」蓋在「盒子」上。</p><p>當你看到一把機械鍵盤，其<strong>最外一圈是與鍵盤正面處於同一平面的邊框</strong>時，這通常就是「天包地」結構。</p><p>作為一種經典且普遍的設計，「天包地」憑藉其<strong>穩定性和經濟性</strong>，在機械鍵盤領域中依然佔有重要地位。</p><h3 id="天包地的優點與缺點" tabindex="-1">天包地的優點與缺點 <a class="header-anchor" href="#天包地的優點與缺點" aria-label="Permalink to &quot;天包地的優點與缺點&quot;">​</a></h3><ul><li>✅ 優點</li></ul><ol><li><strong>結構穩定</strong>：上蓋包裹底殼，結合點多，整體感覺堅固。</li><li><strong>生產成本較低</strong>：模具設計相對簡單，是傳統成熟的方案。</li><li><strong>維修/改裝方便</strong>：擰開底殼螺絲即可打開，方便更換軸體、加裝吸音棉。</li></ol>',20)])])}const f=r(e,[["render",i]]);export{b as __pageData,f as default};
